import{_ as i,C as c,o as n,c as s,j as d,a as e,E as o,a5 as a}from"./chunks/framework.Dep_XxFZ.js";const T=JSON.parse('{"title":"滚动条","description":"","frontmatter":{},"headers":[],"relativePath":"components/scrollbar.md","filePath":"components/scrollbar.md","lastUpdated":1787403679000}'),h={name:"components/scrollbar.md"},b={id:"滚动条",tabindex:"-1"};function u(p,t,m,f,g,x){const l=c("Badge"),r=c("XhDemo");return n(),s("div",null,[d("h1",b,[t[0]||(t[0]=e("滚动条 ",-1)),o(l,{type:"info",text:"scrollbar"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#滚动条","aria-label":'Permalink to "滚动条 <Badge type="info" text="scrollbar" />"'},"​",-1))]),t[3]||(t[3]=a('<p>自绘的滚动条，挂在<strong>任意一个</strong>滚动容器上：表格的滚动盒、虚拟滚动的视口、随手一个 <code>overflow: auto</code> 的 div 都行。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>原生滚动条在各平台长得不一样，而设计稿要求一致。</li><li>滚动容器不归组件管（表格、虚拟列表、你自己的布局），但滚动条要跟库里其余部分一个样。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>容器与滚动条一起要：用<a href="./scroll-area">滚动区域</a>，它把视口、内容与两条滚动条打包好了。</li><li>只是想让原生滚动条细一点：<code>scrollbar-width: thin</code> 就够，不必换掉整套交互。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>挂在作者给的滚动容器上，与它是不是本组件的后代无关；挂上后容器带 <code>data-xh-scrollbar</code>，原生滚动条的外观自动藏起来。</li><li>四种露面时机（<code>auto</code> / <code>always</code> / <code>scroll</code> / <code>hover</code>），带收起延时；露出与收起都淡变。</li><li>拖滑块、点轨道跳转、RTL 双向换算、滑块像素下限都在库里。</li><li><code>focusable</code> 打开后滑块进 Tab 序并报 <code>role=&quot;scrollbar&quot;</code>，方向键与翻页键可用。</li><li>触屏（粗指针）上默认交给原生滚动，<code>forceVisible</code> 打开才画。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="挂在自己的滚动容器上" tabindex="-1">挂在自己的滚动容器上 <a class="header-anchor" href="#挂在自己的滚动容器上" aria-label="Permalink to &quot;挂在自己的滚动容器上&quot;">​</a></h3><p>滚动容器归你，滚动条只要拿到它；把节点交给 scrollable 即可</p>',10)),o(r,{src:"scrollbar/01-basic"}),t[4]||(t[4]=d("h3",{id:"横向-键盘可达",tabindex:"-1"},[e("横向 + 键盘可达 "),d("a",{class:"header-anchor",href:"#横向-键盘可达","aria-label":'Permalink to "横向 + 键盘可达"'},"​")],-1)),t[5]||(t[5]=d("p",null,"focusable 让滑块进 Tab 序并报 role=scrollbar，方向键与翻页键可用",-1)),o(r,{src:"scrollbar/02-focusable"}),t[6]||(t[6]=d("h3",{id:"横竖两条",tabindex:"-1"},[e("横竖两条 "),d("a",{class:"header-anchor",href:"#横竖两条","aria-label":'Permalink to "横竖两条"'},"​")],-1)),t[7]||(t[7]=d("p",null,"同一个容器挂两条，gutter 让各自在末端让出交叉口，XhScrollbarCorner 把那一格补上",-1)),o(r,{src:"scrollbar/03-both-axes"}),t[8]||(t[8]=d("h3",{id:"四种露面时机",tabindex:"-1"},[e("四种露面时机 "),d("a",{class:"header-anchor",href:"#四种露面时机","aria-label":'Permalink to "四种露面时机"'},"​")],-1)),t[9]||(t[9]=d("p",null,"auto 溢出就露、always 恒露、scroll 滚动时露、hover 指针进入才露；收起都是淡出",-1)),o(r,{src:"scrollbar/04-types"}),t[10]||(t[10]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-scrollbar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhScrollbarCorner</code> <code>XhScrollbarRoot</code> <code>XhScrollbarThumb</code> <code>XhScrollbarTrack</code></td></tr><tr><td>组合式函数</td><td><code>useScrollbar</code></td></tr><tr><td>状态机</td><td><code>scrollbarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/scrollbar.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;scrollbar&quot;</code>：<strong><code>root</code></strong> · <strong><code>track</code></strong> · <strong><code>thumb</code></strong> · <code>corner</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>这条滚动条管哪条轴，默认 vertical。</td></tr><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td><td>露面的时机，默认 hover。</td></tr><tr><td><code>hideDelay</code></td><td><code>number</code></td><td></td><td>收起前的等待毫秒（type 为 scroll / hover 时生效），默认 600。</td></tr><tr><td><code>minThumbSize</code></td><td><code>number</code></td><td></td><td>滑块最短多少像素，默认 20。长文档里的滑块再短也按得住。</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>方向键一步滚多少像素，默认 40。翻页键按视口长度走，不看这个值。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，换的是滚动条厚度。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：不接指针也不接键盘，恒不显形。</td></tr><tr><td><code>focusable</code></td><td><code>boolean</code></td><td></td><td>滑块进 Tab 序并报 role=scrollbar，默认 false。 缺省不进：滚动容器自己已经能用键盘滚，再给每条滚动条一个 Tab 停靠点， 长页面上会平白多出十几站。要键盘操作滑块本身时才开。</td></tr><tr><td><code>controls</code></td><td><code>string</code></td><td></td><td>被控滚动容器的 id；focusable 时落到滑块的 aria-controls 上（没给就用容器自己的 id）。</td></tr><tr><td><code>gutter</code></td><td><code>boolean</code></td><td></td><td>横竖两条同时摆着时，各自在末端让出交叉口那一格：竖条不伸到底、横条不伸到头。 交叉口由其中一条里的 corner 部件补上。</td></tr><tr><td><code>forceVisible</code></td><td><code>boolean</code></td><td></td><td>触屏设备（粗指针）上也显形，默认 false：触屏没有悬停、拖滑块也不如直接划内容， 缺省交给原生滚动，本组件整条不显形并带 data-native。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>排版方向，默认随文档。只影响横轴：RTL 下滚动量的正负、指针位移的方向都要翻一次。 必须显式给：组件不读计算样式，看不见从 RTL 祖先继承来的方向。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ScrollbarTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onScrollStart</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>开始滚了（停手 120ms 才算一段结束，中途连滚不重复通知）。</td></tr><tr><td><code>onScrollEnd</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>一段滚动结束。</td></tr><tr><td><code>onDragStart</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>按住滑块。</td></tr><tr><td><code>onDragEnd</code></td><td><code>(details: ScrollbarScrollDetails) =&gt; void</code></td><td></td><td>松开滑块。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>CustomEvent</code></td><td></td></tr><tr><td><code>scroll-start</code></td><td>``</td><td>开始滚了；detail 为 <code>{ offset: number, max: number }</code></td></tr><tr><td><code>scroll-end</code></td><td>``</td><td>一段滚动结束（停手 120ms）；detail 同上</td></tr><tr><td><code>drag-start</code></td><td>``</td><td>按住滑块；detail 同上</td></tr><tr><td><code>drag-end</code></td><td>``</td><td>松开滑块；detail 同上</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhScrollbarRoot</code></td><td><code>default</code></td><td><code>ScrollbarRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>corner</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>hidden</code> · <code>visible</code> · <code>hiding</code> · <code>dragging</code></p><p><strong>事件</strong>：<code>MEASURE</code> · <code>SCROLL</code> · <code>SCROLL.IDLE</code> · <code>POINTER.ENTER</code> · <code>POINTER.LEAVE</code> · <code>DRAG.START</code> · <code>DRAG.MOVE</code> · <code>DRAG.END</code> · <code>TRACK.CLICK</code> · <code>STEP</code> · <code>SCROLL.TO</code> · <code>after.hideDelay</code></p><p><strong>判据</strong>：<code>isHoverType</code> · <code>isScrollType</code> · <code>staysVisible</code> · <code>canInteract</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useScrollbar</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td></tr><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td></tr><tr><td><code>overflow</code></td><td><code>boolean</code></td><td>内容比可视区长。不溢出时 auto 档整条不显形。</td></tr><tr><td><code>visible</code></td><td><code>boolean</code></td><td>这一刻该不该显形（已把 type、disabled 与触屏原生那一路都算进去）。</td></tr><tr><td><code>native</code></td><td><code>boolean</code></td><td>交给了原生滚动：粗指针设备且没开 forceVisible，整条不显形。</td></tr><tr><td><code>hover</code></td><td><code>boolean</code></td><td>指针此刻在滚动容器或滚动条上。</td></tr><tr><td><code>dragging</code></td><td><code>boolean</code></td><td>手正按在滑块上。</td></tr><tr><td><code>scrolling</code></td><td><code>boolean</code></td><td>这一段滚动还在进行中。</td></tr><tr><td><code>thumbSize</code></td><td><code>number</code></td><td>滑块长度占轨道的比例，0-1。</td></tr><tr><td><code>thumbOffset</code></td><td><code>number</code></td><td>滑块起点占轨道的比例，0-1。</td></tr><tr><td><code>scroll</code></td><td><code>number</code></td><td>距逻辑起始缘的滚动量（px）。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td>还能往前滚多少（px）。</td></tr><tr><td><code>scrollTo</code></td><td><code>(offset: number) =&gt; void</code></td><td>滚到某个绝对位置（px），越界自动夹。</td></tr><tr><td><code>scrollBy</code></td><td><code>(delta: number) =&gt; void</code></td><td>相对当前位置滚若干像素。</td></tr><tr><td><code>measure</code></td><td><code>() =&gt; void</code></td><td>重新量一遍。内容长短变了会自动重量（MutationObserver 盯着容器子树）， 这个出口留给量不到的那些：容器换了、内容在 Shadow DOM 里、或是自定义元素内部改的。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getThumbProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCornerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>交叉口补丁，写在其中一条的 root 里；跟着这一条的显隐走。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>focus in thumb, focusable, 与本轴同向</td><td>往回滚一步（step，默认 40px）；交叉轴的那一个不拦，照常交给页面</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>focus in thumb, focusable, 与本轴同向</td><td>往前滚一步</td></tr><tr><td><code>PageUp</code></td><td>focus in thumb, focusable</td><td>往回滚一屏（按滚动容器的可视长度）</td></tr><tr><td><code>PageDown</code></td><td>focus in thumb, focusable</td><td>往前滚一屏</td></tr><tr><td><code>Home</code></td><td>focus in thumb, focusable</td><td>滚到起点</td></tr><tr><td><code>End</code></td><td>focus in thumb, focusable</td><td>滚到终点</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focusable</td><td>滑块是一个 Tab 停靠点；不开 focusable 时整条退出 Tab 序，也对读屏隐藏</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-hidden</code></td><td>undefined | &#39;true&#39;</td></tr><tr><td><code>thumb</code></td><td><code>aria-controls</code></td><td>props.controls | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-label</code></td><td>props.translations.thumb | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-orientation</code></td><td>props.orientation | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuemax</code></td><td>Math.round(max) | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuemin</code></td><td>0 | undefined</td></tr><tr><td><code>thumb</code></td><td><code>aria-valuenow</code></td><td>Math.round(metrics.scroll) | undefined</td></tr><tr><td><code>thumb</code></td><td><code>role</code></td><td>&#39;scrollbar&#39; | undefined</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/scrollbar.css</code> 按部件选择：<code>[data-scope=&quot;scrollbar&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-gutter</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-native</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-scrolling</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>root</code></td><td><code>data-type</code></td><td>props.type</td></tr><tr><td><code>track</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>track</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>thumb</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>thumb</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>thumb</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>corner</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>corner</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>corner</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-scrollbar-corner-bg</code> · <code>--xh-scrollbar-gutter</code> · <code>--xh-scrollbar-thickness-lg</code> · <code>--xh-scrollbar-thickness-md</code> · <code>--xh-scrollbar-thickness-sm</code> · <code>--xh-scrollbar-thumb-bg</code> · <code>--xh-scrollbar-thumb-bg-active</code> · <code>--xh-scrollbar-thumb-bg-disabled</code> · <code>--xh-scrollbar-thumb-bg-hover</code> · <code>--xh-scrollbar-thumb-radius</code> · <code>--xh-scrollbar-track-bg</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li><a href="./scroll-area">滚动区域</a>就是视口加两条本组件的组装：它的轨道、滑块与交叉口戴的正是本组件的 scope。</li><li><a href="./table">表格</a>放进滚动区即可滚；<a href="./virtualizer">虚拟滚动</a>的视口给个 id，用 <code>controls</code> 挂上即可。</li><li>两条轴各摆一个，都打开 <code>gutter</code> 让出交叉口，<code>corner</code> 写在其中一条里补上那一格。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>藏原生滚动条只藏外观（<code>scrollbar-width: none</code>），别动滚动能力——键盘与滚轮仍要走原生通路。</li><li>触摸设备保留原生滚动，别给 <code>hover</code> 档：手指没有&quot;悬停&quot;。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>给每条滚动条都开 <code>focusable</code>：长页面上会平白多出十几个 Tab 停靠点。</li><li>用它替代滚轮拦截：这个组件不接管滚轮，嵌套滚动的冲突要在布局上解决。</li></ul>',48))])}const P=i(h,[["render",u]]);export{T as __pageData,P as default};
